// Check the env vars inside bootHarness() rather than at module scope:
// a module-level throw would surface as a vitest collection error for the
// whole file, while a thrown inside bootHarness() becomes a normal test
// failure that doesn't tear down the rest of the suite.
async function bootHarness(): Promise<Rig> {
  const wsUrl = process.env.ARCHASTRO_HARNESS_WS_URL;
  const controlUrl = process.env.ARCHASTRO_HARNESS_CONTROL_URL;
  if (!wsUrl || !controlUrl) {
    throw new Error(
      "Channel contract tests require ARCHASTRO_HARNESS_WS_URL and " +
        "ARCHASTRO_HARNESS_CONTROL_URL — set by global-setup.ts."
    );
  }
  const client = new HarnessServiceClient({ wsUrl, controlUrl });
  await client.reset();
  const socket = await client.openSocket();
  return { client, socket };
}

function nextPush(
  subscribe: (cb: (payload: unknown) => void) => () => void,
  timeoutMs = 500
): Promise<unknown> {
  return new Promise((resolve, reject) => {
    let settled = false;
    let unsubscribe: (() => void) | null = null;
    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      unsubscribe?.();
      reject(new Error("push not received in time"));
    }, timeoutMs);
    unsubscribe = subscribe((payload) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      unsubscribe?.();
      resolve(payload);
    });
    if (settled) unsubscribe();
  });
}

describe("EpicsChannel.joinEpic (task_epics:{public_id})", () => {
  let rig: Rig;
  beforeEach(async () => {
    rig = await bootHarness();
  });
  afterEach(() => {
    rig.client.closeAllSockets();
  });

  it("joins and receives a contract-valid reply", async () => {
    const channel = await EpicsChannel.joinEpic(rig.socket, "test-id");
    expect(channel).toBeInstanceOf(EpicsChannel);
    expect(channel.joinResponse).toBeDefined();
  });

  it("surfaces an application-level error reply as ChannelJoinError", async () => {
    await rig.client.registerScenario({
      topic: "task_epics:test-id",
      onJoin: [{ type: "replyError", payload: { reason: "test_error" } }],
    });

    const err = await EpicsChannel.joinEpic(rig.socket, "test-id").catch((e: unknown) => e);
    expect(err).toBeInstanceOf(ChannelJoinError);
    expect((err as ChannelJoinError).response).toEqual({ reason: "test_error" });
  });
});

